import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { redirect } from "next/navigation";
import Link from "next/link";

export default async function SettingsPage() {
  const session = await getServerSession(authOptions);
  if (!session) redirect("/login");
  const user = session.user as any;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex">
      <aside className="w-64 bg-slate-900 border-r border-slate-800 hidden md:flex flex-col">
        <div className="p-6 border-b border-slate-800">
          <h1 className="text-xl font-bold tracking-wider text-indigo-400">CivicBank</h1>
        </div>
        <nav className="flex-1 p-4 space-y-1.5">
          <Link href="/dashboard" className="flex items-center px-4 py-2.5 rounded-lg text-sm text-slate-400 hover:bg-slate-800">Overview</Link>
          <Link href="/dashboard/settings" className="flex items-center px-4 py-2.5 rounded-lg text-sm bg-indigo-600/10 text-indigo-400 border border-indigo-500/20">Settings</Link>
        </nav>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-y-auto">
        <header className="bg-slate-900 border-b border-slate-800 h-16 flex items-center px-6">
          <h2 className="text-lg font-semibold text-slate-200">Account Settings</h2>
        </header>
        <div className="p-6 max-w-5xl w-full mx-auto space-y-6">
          <div className="bg-slate-900 border border-slate-800 p-6 rounded-xl shadow-lg space-y-4">
            <h3 className="text-base font-semibold text-white">Profile Preferences</h3>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Registered Name</label>
              <input type="text" disabled value={user?.name || ""} className="w-full rounded-lg bg-slate-950 border border-slate-800 px-3 py-2 text-sm text-slate-300" />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Email Address</label>
              <input type="email" disabled value={user?.email || ""} className="w-full rounded-lg bg-slate-950 border border-slate-800 px-3 py-2 text-sm text-slate-300" />
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}